class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution1:
    def sort_list(self, head):
        """Sort a linked list using merge sort."""
        if head is None or head.next is None:
            return head

        prev = None
        slow = head
        fast = head
        while fast is not None and fast.next is not None:
            prev = slow
            fast = fast.next.next
            slow = slow.next

        prev.next = None
        l1 = self.sort_list(head) 
        l2 = self.sort_list(slow)
        return self.merge(l1, l2)

    def merge(self, l1, l2):
        """Merge two sorted linked lists."""
        result = ListNode(0)
        tmp = result
        while l1 is not None and l2 is not None:
            if l1.val < l2.val:
                tmp.next = l1
                l1 = l1.next
            else:
                tmp.next = l2
                l2 = l2.next
            tmp = tmp.next
        if l1 is not None:
            tmp.next = l1
        if l2 is not None:
            tmp.next = l2
        return result.next

class Solution2:
    tail = ListNode(0)
    nextSubList = ListNode(0)

    def sort_list(self, head):
        """Sort a linked list using iterative merge sort with logarithmic space complexity."""
        if head is None or head.next is None:
            return head
        n = self.get_count(head)
        start = head
        dummy_head = ListNode(0)
        size = 1
        while size < n:
            self.tail = dummy_head
            while start is not None:
                if start.next is None:
                    self.tail.next = start
                    break
                mid = self.split(start, size)
                self.merge(start, mid)
                start = self.nextSubList
            start = dummy_head.next
            size *= 2
        return dummy_head.next

    def split(self, start, size):
        """Split the linked list into two halves based on the given size."""
        midPrev = start
        end = start.next
        index = 1
        while index < size and (midPrev.next is not None or end.next is not None):
            if end.next is not None:
                end = (end.next.next if end.next.next is not None else end.next)
            if midPrev.next is not None:
                midPrev = midPrev.next
            index += 1
        mid = midPrev.next
        midPrev.next = None
        self.nextSubList = end.next
        end.next = None
        return mid

    def merge(self, list1, list2):
        """Merge two sorted linked lists."""
        dummy_head = ListNode(0)
        new_tail = dummy_head
        while list1 is not None and list2 is not None:
            if list1.val < list2.val:
                new_tail.next = list1
                list1 = list1.next
            else:
                new_tail.next = list2
                list2 = list2.next
            new_tail = new_tail.next
        new_tail.next = (list1 if list1 is not None else list2)
        while new_tail.next is not None:
            new_tail = new_tail.next
        self.tail.next = dummy_head.next
        self.tail = new_tail

    def get_count(self, head):
        """Get the count of nodes in the linked list."""
        cnt = 0
        ptr = head
        while ptr is not None:
            ptr = ptr.next
            cnt += 1
        return cnt

class Solution3:
    def sort_list(self, head):
        """Sort a linked list using merge sort."""
        if head is None or head.next is None:
            return head
        mid = self.get_mid(head)
        left = self.sort_list(head)
        right = self.sort_list(mid)
        return self.merge_list(left, right)

    def merge_list(self, left, right):
        """Merge two sorted linked lists and return the merged list."""
        pre = ListNode(-1)
        tmp = pre
        while left is not None and right is not None:
            if left.val < right.val:
                tmp.next = left
                left = left.next
            else:
                tmp.next = right
                right = right.next
            tmp = tmp.next
        if left is not None:
            tmp.next = left
        elif right is not None:
            tmp.next = right
        return pre.next

    def get_mid(self, head):
        """Find the middle node of the linked list."""
        midPrev = None
        while head is not None and head.next is not None:
            midPrev = (head if midPrev is None else midPrev.next)
            head = head.next.next
        mid = midPrev.next
        midPrev.next = None
        return mid

class Solution4:
    def sort_list(self, head):
        """Sort a linked list using built-in sorting."""
        if head is None:
            return head
        vals = []
        tmp = head
        while tmp is not None:
            vals.append(tmp.val)
            tmp = tmp.next
        vals.sort()
        pre = ListNode(-1)
        newHead = ListNode(vals[0])
        pre.next = newHead
        for i in range(1, len(vals)):
            next_node = ListNode(vals[i])
            newHead.next = next_node
            newHead = newHead.next
        return pre.next
