        """Merge two sorted linked lists."""
        result = ListNode(0)
        tmp = result
        while l1 is not None and l2 is not None:
            if l1.val < l2.val:
                tmp.next = l1
                l1 = l1.next
            else:
                tmp.next = l2
                l2 = l2.next
            tmp = tmp.next
        if l1 is not None:
            tmp.next = l1
        if l2 is not None:
            tmp.next = l2
        return result.next

